bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 60
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = true || exit 61
python3 - <<'PY'
import json,subprocess,sys
allowed={1613:"profile",1695:"video",4640:"sticker"}
rows=[]
for page in range(16):
 r=subprocess.run(["python3","scripts/userbot_topic_audit_client.py","--chat-id","-1002373696859","--page",str(page)],capture_output=True,text=True,timeout=125)
 if r.returncode:sys.exit(62)
 data=[json.loads(x.split("=",1)[1]) for x in r.stdout.splitlines() if x.startswith("USERBOT_TOPIC_AUDIT=")]
 if len(data)!=1 or data[0].get("chat")!="video":sys.exit(63)
 rows+=data[0].get("rows",[])
 if not data[0].get("has_more"):break
else:sys.exit(64)
byid={x["topic_id"]:x for x in rows}
if len(byid)!=len(rows):sys.exit(65)
extra=sorted(t for t,r in byid.items() if r.get("post_button")=="PRESENT" and t not in allowed)
missing=sorted(t for t in allowed if byid.get(t,{}).get("post_button")!="PRESENT")
for topic in (4291,4672,1605,1634,1723,1):
 if byid.get(topic,{}).get("post_button")=="PRESENT":sys.exit(66)
for topic in (4291,4672,1605,1634,1723):
 q=f"SELECT state,pinned FROM topic_dm_entry_pins WHERE chat_id=-1002373696859 AND message_thread_id={topic}"
 p=subprocess.run(["docker","exec","deploy-postgres-1","psql","-X","-q","-v","ON_ERROR_STOP=1","-U","gace","-d","gaybbs","-Atc",q],capture_output=True,text=True,timeout=30)
 if p.returncode or p.stdout.strip()!="needs_reconcile|f":sys.exit(67)
body="Master-approved video-only specialist buttons: independent final resident Userbot full topic scan. "+json.dumps({"topics_scanned":len(byid),"approved":allowed,"missing_approved":missing,"extra_button_topics":extra,"previously_wrong_topics_verified_no_button":[4291,4672,1605,1634,1723,1]},ensure_ascii=False,separators=(',',':'))
p=subprocess.run(["gh","api","repos/seigo-gace/GateApp-Bot/issues/68/comments","-f","body="+body],capture_output=True,text=True,timeout=40)
if p.returncode:sys.exit(68)
if extra:sys.exit(70+len(extra))
if missing:sys.exit(80+len(missing))
print("VIDEO_ONLY_THREE_SPECIALIST_TOPICS=PASS;OTHER_TOPIC_POST_BUTTONS_ZERO=PASS")
PY
